        function installationCheck() {
            // Check architecture first so Intel users aren't told to update macOS.
            // hw.optional.arm64 also detects Apple Silicon under Rosetta.
            var isAppleSilicon = false;
            try {
                isAppleSilicon = system.sysctl('hw.optional.arm64') == 1;
            } catch (e) {} // Ignore unavailable sysctl keys.
            if (!isAppleSilicon) {
                my.result.title = 'Apple Silicon Required';
                my.result.message = 'Gnosis VPN requires a Mac with Apple Silicon (M1 or later). Intel-based Macs are not supported.';
                my.result.type = 'Fatal';
                return false;
            }

            if (system.compareVersions(system.version.ProductVersion, '__MIN_OS_MACOS__') < 0) {
                my.result.title = 'macOS __MIN_OS_MACOS__ or Later Required';
                my.result.message = 'Gnosis VPN requires macOS __MIN_OS_MACOS__ or later. You are running macOS ' + system.version.ProductVersion + '. Please update macOS in System Settings > Software Update.';
                my.result.type = 'Fatal';
                return false;
            }

            return true;
        }

        // Radio-style groups. Installer keeps a click on the clicked choice and re-evaluates only the others,
        // so a member stays ticked only while no other member is: ticking another one unticks it.
        // Unticking the pick empties the group only when allowNone is true; otherwise the first member
        // re-evaluated takes over (for two members, the other one).
        function exclusiveSelected(selfId, groupIds, allowNone) {
            for (var i = 0; i < groupIds.length; i++) {
                var other = groupIds[i];
                if (other !== selfId && choices[other] && choices[other].selected) {
                    return false;
                }
            }
            return allowNone ? my.choice.selected : true;
        }

        // An installed service can be kept as is (postinstall keep mode), so only then may no network be ticked.
        function hasServiceSetup() {
            return system.files.fileExistsAtPath('/Library/LaunchDaemons/com.gnosisvpn.gnosisvpnclient.plist')
                && system.files.fileExistsAtPath('/etc/gnosisvpn/config.toml');
        }


















